package vn.edu.fpt.seal.modules.prize.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import vn.edu.fpt.seal.modules.prize.dto.*; import vn.edu.fpt.seal.modules.prize.service.PrizeService; import java.util.List; import java.util.UUID;
@RestController @RequestMapping("/prizes") @RequiredArgsConstructor public class PrizeController{private final PrizeService service; @GetMapping @PreAuthorize("isAuthenticated()") public ResponseEntity<Page<PrizeResponse>> list(@RequestParam(required=false) UUID eventId,@RequestParam(required=false) UUID trackId,@RequestParam(required=false) UUID teamId,Pageable p){return ResponseEntity.ok(service.list(eventId,trackId,teamId,p));} @GetMapping("/{id}") @PreAuthorize("isAuthenticated()") public ResponseEntity<PrizeResponse> get(@PathVariable UUID id){return ResponseEntity.ok(service.get(id));} @PostMapping @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<PrizeResponse> create(@Valid @RequestBody CreatePrizeRequest r){return ResponseEntity.ok(service.create(r));} @PatchMapping("/{id}") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<PrizeResponse> update(@PathVariable UUID id,@Valid @RequestBody UpdatePrizeRequest r){return ResponseEntity.ok(service.update(id,r));} @DeleteMapping("/{id}") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<Void> delete(@PathVariable UUID id){service.delete(id); return ResponseEntity.noContent().build();}
 // Thu hồi giải (giữ nguyên lịch sử, không xóa cứng)
 @PostMapping("/{id}/revoke") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<PrizeResponse> revoke(@PathVariable UUID id,@Valid @RequestBody RevokePrizeRequest r,Authentication auth){return ResponseEntity.ok(service.revoke(id,r,auth));}
 // Chuyển giải sang đội khác (ghi lịch sử + timeline cả hai đội)
 @PostMapping("/{id}/reassign") @PreAuthorize("hasRole('COORDINATOR')") public ResponseEntity<PrizeResponse> reassign(@PathVariable UUID id,@Valid @RequestBody ReassignPrizeRequest r,Authentication auth){return ResponseEntity.ok(service.reassign(id,r,auth));}
 // Lịch sử thu hồi/chuyển giải của một giải thưởng
 @GetMapping("/{id}/revisions") @PreAuthorize("isAuthenticated()") public ResponseEntity<List<PrizeRevisionResponse>> revisions(@PathVariable UUID id){return ResponseEntity.ok(service.revisions(id));}}
